describe('Sticky Header', () => {
    beforeEach(() => {
        cy.visit('/'); // Replace with the actual URL of the application
    });

    it('should display the header at the top of the page when scrolling down', () => {
        cy.get('header').should('be.visible'); // Ensure header is visible initially
        cy.scrollTo(0, 500); // Scroll down the page
        cy.get('header').should('have.class', 'sticky'); // Check if header has sticky class
        cy.get('header').should('be.visible'); // Ensure header is still visible
    });

    it('should not lose visibility when scrolling back up', () => {
        cy.get('header').should('be.visible'); // Ensure header is visible initially
        cy.scrollTo(0, 500); // Scroll down the page
        cy.scrollTo(0, 0); // Scroll back to the top
        cy.get('header').should('have.class', 'sticky'); // Check if header still has sticky class
        cy.get('header').should('be.visible'); // Ensure header is still visible
    });
});
